/// Updates the webhook configuration for the specified branch's Neon Auth integration. Webhooks notify an external endpoint when auth events occur, such as user creation or sign-in.
///
/// [projectId] The Neon project ID
/// [branchId] The Neon branch ID
/// [enabled] Whether the webhook is active.
/// [webhookUrl] Destination URL that receives webhook event payloads.
/// [enabledEvents] Event types that trigger this webhook. Covers user
///   lifecycle, email/OTP delivery, organization invitations, and phone
///   verification events; see the enum for exact values.
/// [timeoutSeconds] Maximum time, in seconds, to wait for a response from the
///   webhook endpoint.
Future<NeonAuthWebhookConfig> updateAuthWebhookConfig(ClientConfig config,
    {required String projectId,
    required String branchId,
    required bool enabled,
    SdkOptional<String> webhookUrl = const SdkOmitted(),
    SdkOptional<List<NeonAuthWebhookConfigEnabledEventsItem>> enabledEvents = const SdkOmitted(),
    SdkOptional<int> timeoutSeconds = const SdkOmitted(),
    RequestOptions? requestOptions}) async {
  sdkValidatePattern('project_id', projectId, '^[a-z0-9-]{1,60}\$');
  sdkValidatePattern('branch_id', branchId, '^[a-z0-9-]{1,60}\$');
  if (timeoutSeconds is SdkPresent<int>) {
    validateRange('timeout_seconds', timeoutSeconds.value, min: 1, max: 10);
  }

  return (await sdkRequest<NeonAuthWebhookConfig>('PUT',
          '/projects/${Uri.encodeComponent(projectId.toString())}/branches/${Uri.encodeComponent(branchId.toString())}/auth/webhooks',
          config: config,
          body: {
            'enabled': enabled,
            'webhook_url': SdkUtils.unwrapOptional(webhookUrl),
            'enabled_events': SdkUtils.unwrapOptional(enabledEvents),
            'timeout_seconds': SdkUtils.unwrapOptional(timeoutSeconds)
          },
          decoder: SdkResponseDecoder.json,
          operationId: 'updateAuthWebhookConfig',
          fromJsonRaw: (value) => NeonAuthWebhookConfig.fromJson(value as Map<String, dynamic>),
          options: requestOptions,
          errors: {'default': (value) => GeneralError.fromJson(value as Map<String, dynamic>)}))
      .data;
}
